import assert from 'node:assert/strict';import{pathToFileURL}from'node:url';
const root=new URL('../../..',import.meta.url).pathname.replace(/\/$/,'');const {betterAuthReference}=await import(pathToFileURL(root+'/cli/tests/fixtures/rust_better_auth_reference.mjs'));const {betterAuth}=await import(pathToFileURL(process.env.FORKLAUNCH_TEST_BETTER_AUTH_DEPENDENCIES+'/node_modules/better-auth/dist/index.mjs'));
const rows=[];for(const mode of ['manual','signup-send','required','required-no-send','signin-only','required-signin','required-no-hook','signup-sync-error','signup-async-error','signup-background','signin-sync-error','signin-async-error','duplicate-required']){
 const ref=await betterAuthReference(root);let sends=0,dispatch=0;const sessionCounts=[];const tasks=[];
 const requireEmailVerification=mode.startsWith('required')||(mode.startsWith('signin-')&&mode!=='signin-only')||mode==='duplicate-required';
 const hook=input=>{sends++;sessionCounts.push(ref.database.session.length);assert.ok(input.token);if(mode.endsWith('-sync-error'))throw Error('owned');return mode.endsWith('async-error')?Promise.reject(Error('owned')):Promise.resolve();};
 const ev={...(mode==='required-no-hook'?{}:{sendVerificationEmail:hook}),...(['signup-send','signup-sync-error','signup-async-error','signup-background'].includes(mode)?{sendOnSignUp:true}:{}),...(mode==='required-no-send'||mode.startsWith('signin-')||mode==='required-signin'?{sendOnSignUp:false}:{}),...(['signin-only','required-signin','signin-sync-error','signin-async-error'].includes(mode)?{sendOnSignIn:true}:{})};
 const auth=betterAuth({...ref.config,emailAndPassword:{...ref.config.emailAndPassword,requireEmailVerification},emailVerification:ev,advanced:{...ref.config.advanced,...(mode==='signup-background'?{backgroundTasks:{handler:p=>{dispatch++;tasks.push(p);}}}:{})},logger:{disabled:true},rateLimit:{enabled:false}});
 const call=(route,body)=>auth.handler(new Request('http://localhost:3000/api/auth'+route,{method:'POST',headers:{origin:'http://localhost:3000','content-type':'application/json'},body:JSON.stringify(body)}));
 const input={name:'Owned',firstName:'Owned',lastName:'User',email:'options@example.test',password:'owned-options-password'};
 const signup=await call('/sign-up/email',input);const signupBody=await signup.text();const before=sends;
 const signin=await call(mode==='duplicate-required'?'/sign-up/email':'/sign-in/email',input);const signinBody=await signin.text();await Promise.all(tasks);
 rows.push({mode,signup:signup.status,signupToken:signupBody.includes('"token":null')?'null':signupBody.includes('"token":')?'present':'none',next:signin.status,nextCode:JSON.parse(signinBody||'{}').code,sendsOnSignup:before,sendsNext:sends-before,dispatch,sessionCounts,users:ref.database.user.length,accounts:ref.database.account.length,sessions:ref.database.session.length});
}
const expected={manual:[200,200,0,0,2],'signup-send':[200,200,1,0,2],required:[200,403,1,0,0],'required-no-send':[200,403,0,0,0],'signin-only':[200,200,0,0,2],'required-signin':[200,403,0,1,0],'required-no-hook':[200,403,0,0,0],'signup-sync-error':[500,401,1,0,0],'signup-async-error':[200,200,1,0,2],'signup-background':[200,200,1,0,2],'signin-sync-error':[200,500,0,1,0],'signin-async-error':[200,403,0,1,0],'duplicate-required':[200,200,1,0,0]};
for(const row of rows){assert.deepEqual([row.signup,row.next,row.sendsOnSignup,row.sendsNext,row.sessions],expected[row.mode]);assert.ok(row.sessionCounts.every(n=>n===0));}
